@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
public abstract class AcceptanceBase {

	private static final AtomicInteger SEQ = new AtomicInteger(0);

	@Autowired
	protected MockMvc mvc;

